let lang='en',promptEvent;try{lang=localStorage.getItem('waraq-lang')||'en';}catch{}const $=s=>document.querySelector(s),t=(en,ar)=>lang==='ar'?ar:en;function translate(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-en]').forEach(e=>e.textContent=e.dataset[lang]);$('#language').textContent=t('العربية','English');$('#installed').textContent=matchMedia('(display-mode: standalone)').matches||navigator.standalone?t('Waraq is running as an installed app.','يعمل ورق كتطبيق مثبت.'):'';}$('#language').onclick=()=>{lang=lang==='ar'?'en':'ar';try{localStorage.setItem('waraq-lang',lang);}catch{}translate();};translate();window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();promptEvent=e;$('#install').hidden=false;});$('#install').onclick=async()=>{if(!promptEvent)return;await promptEvent.prompt();await promptEvent.userChoice;promptEvent=null;$('#install').hidden=true;};window.addEventListener('appinstalled',()=>{$('#install').hidden=true;$('#installed').textContent=t('Waraq installed.','تم تثبيت ورق.');});const registration='serviceWorker'in navigator?navigator.serviceWorker.register('./sw.js'):Promise.reject(Error('Unavailable'));registration.catch(()=>{});$('#prepare').onclick=async()=>{const b=$('#prepare'),s=$('#status'),p=$('#progress');b.disabled=true;p.hidden=false;s.textContent=t('Preparing…','جارٍ التحضير…');let timer,channel;try{await registration;const r=await navigator.serviceWorker.ready;channel=new MessageChannel();await new Promise((resolve,reject)=>{timer=setTimeout(()=>reject(Error('timeout')),180000);channel.port1.onmessage=e=>{if(e.data.progress){p.max=e.data.total;p.value=e.data.progress;s.textContent=t('Saving files: ','حفظ الملفات: ')+e.data.progress+'/'+e.data.total;}if(e.data.done)resolve();if(e.data.error)reject(Error(e.data.error));};r.active.postMessage({type:'CACHE_ALL'},[channel.port2]);});s.textContent=t('Ready. Reopen this same address offline.','جاهز. افتح العنوان نفسه دون اتصال.');}catch{s.textContent=t('Offline preparation is incomplete. Reconnect and try again, or download the website ZIP.','التحضير غير مكتمل. اتصل وحاول مجدداً أو نزّل حزمة الموقع.');}finally{clearTimeout(timer);channel?.port1.close();b.disabled=false;}};